// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.rule.storageimport com.roshan.persona.brain.context.SessionIdimport com.roshan.persona.brain.intent.Intentimport com.roshan.persona.brain.skill.ConversationStageimport com.roshan.persona.brain.skill.SkillOutputimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport java.time.Instant/** * NOUS — Conversation state storage interface (Fixes #8). * * When a skill returns [SkillOutput.NeedsInput], the brain: *   1. Persists the current request state via this interface *   2. Returns the prompt to UI *   3. Waits for user's next input *   4. On next input: resumes the skill via [ResumableSkill.resume] * * State machine: *   PROCESSING → NEEDS_INPUT → (user input) → RESUMING → PROCESSING → SUCCESS/FAILURE * * States can also EXPIRE (default 5 min) → discard, fresh routing. * * Real implementation: [CrashSafeConversationStateStorage] (bound via * [com.roshan.persona.brain.di.BrainBindingsModule]) — persists to disk via * :feature:memory's `RoomStateFileStorage` (Room-backed). * * Test fake: `InMemoryConversationStateStorage` in * `src/test/kotlin/.../rule/storage/`. * * @see <a href="docs/spec/module2-spec-review.pdf">§5.2 NeedsInput State Machine</a> */interface ConversationStateStorage {    /** Save a conversation state (when skill pauses for input). */    suspend fun save(state: ConversationStateData): Result<Unit>    /** Get the active (non-expired) conversation state for a session. */    suspend fun getActive(sessionId: SessionId): Result<ConversationStateData?>    /** Mark a conversation state as completed (skill finished). */    suspend fun markCompleted(sessionId: SessionId): Result<Unit>    /** Mark a conversation state as expired (TTL exceeded). */    suspend fun markExpired(sessionId: SessionId): Result<Unit>    /** Delete all conversation states for a session (on session end). */    suspend fun deleteAllForSession(sessionId: SessionId): Result<Unit>    /** Delete all expired states (cleanup job, runs hourly). */    suspend fun deleteExpired(): Result<Int>}/** * Persisted conversation state data. * * Stored in Room `conversation_states` table. Has 5-minute TTL — after which * state is marked EXPIRED and a fresh routing happens on next input. */data class ConversationStateData(    val sessionId: SessionId,    val correlationId: CorrelationId,    val skillId: String,    val intent: Intent,    val stage: ConversationStage,    val partialOutput: SkillOutput?,    val createdAt: Instant,    val expiresAt: Instant,  // createdAt + 5 min (configurable)) {    /** Whether this state has expired. */    fun isExpired(now: Instant = Instant.now()): Boolean = now.isAfter(expiresAt)    companion object {        const val DEFAULT_TTL_MINUTES = 5L        /** Create a new state with default TTL. */        fun create(            sessionId: SessionId,            correlationId: CorrelationId,            skillId: String,            intent: Intent,            partialOutput: SkillOutput?,        ): ConversationStateData {            val now = Instant.now()            return ConversationStateData(                sessionId = sessionId,                correlationId = correlationId,                skillId = skillId,                intent = intent,                stage = ConversationStage.NEEDS_INPUT,                partialOutput = partialOutput,                createdAt = now,                expiresAt = now.plusSeconds(DEFAULT_TTL_MINUTES * 60),            )        }    }}